from pathlib import Path
p=Path('dist/details.js');s=p.read_text(encoding='utf-8').replace("['학명',", "['학명 (변종은 기원 참조)',").replace('약학정보원 본초 처방 예시와 처방정보 100건에서 확인된 연결이 없습니다.','약학정보원 본초 처방 예시, 처방정보 100건과 방약합편 564건에서 확인된 연결이 없습니다.').replace('이름·기원은 식약처 목록과 한약기원사전을 대조했습니다. 외국 공정서의 정의는 해당 문헌 기준입니다.','각 정의의 원문과 공정서를 함께 표시했습니다. 학명의 변종·저자 표기는 기원 정의를 확인하세요.');p.write_text(s,encoding='utf-8')
p=Path('DATA_NOTES.md');s=p.read_text(encoding='utf-8').replace('한글 약재명 토큰이 일치한 경우 연결한다.','한글 약재명 토큰이 일치한 경우 연결한다. 방약합편 564개도 구성 약재의 한글·한자 명칭을 대조하되, 去가 포함된 가감 처방은 자동 연결에서 제외한다.').replace('정확히 일치한 490개 상세 원문을 확인했다.','대표명이 정확히 일치한 490개 상세 원문을 먼저 확인하고, 별도 수록된 포제품·가루 항목과 추가 검색 자료를 대조했다. 최종 기원 연결은 593개다.').replace('`collect_names.py`','`collect_names.py`, `collect_bangyak.py`, `collect_remaining.py`');s+='\n남은 기원 미확인 8항목: 다엽가루, 다투라, 디기탈리스엽, 디기탈리스엽가루, 로얄젤리, 생로얄젤리, 스코폴리아근, 피마자. 원문 검색의 일부 요청은 HTTP 500 오류를 반환했다. 모약재에서 추론하거나 빈 항목을 허위 정보로 채우지 않았다.\n';p.write_text(s,encoding='utf-8')
